  <section class="card"><div class="card-head"><div><h3>Staff Performance</h3></div><span class="data-safe">● Data safe ${d.backup?.last_at?`• backup ${esc(ago(d.backup.last_at))}`:'• automatic backup enabled'}</span></div><div class="staff-performance-grid">${cards||emptyState('No staff profiles','Add or activate your real CRM staff profiles in Admin Settings.')}</div></section>
