  <div class="staff-kpis">${metric('TODAY RECEIVED',t.assigned||0,'＋')}${metric('TODAY COMPLETED',t.completed||0,'✓')}${metric('TODAY WAITING',ts.waiting||0,'◷')}${metric('TODAY PENDING',ts.pending||0,'●')}${metric('NO RESPONSE TODAY',ts.quick_skipped||0,'☎')}${metric('WEEK COMPLETED',w.completed||0,'▤')}${metric('MONTH COMPLETED',m.completed||0,'◉')}${metric('NOT PURCHASED MONTH',ms.not_purchase||0,'×')}${metric('ORDERS MONTH',m.won||0,'📦')}${metric('MONTH WON VALUE',fmtMoney(m.won_value),'₹','money')}</div>
