function buildLeadParams(r,mode){const p=new URLSearchParams();if(!isOwner())p.set('owner',String(state.viewerId));for(const k of ['q','stage','classification','contact','source','temperature'])if(r.query.get(k))p.set(k,r.query.get(k));if(mode==='HOT')p.set('temperature_group','HOT');p.set('page',r.query.get('page')||'1');p.set('limit','50');return p}
async function renderLeads(mode='ALL'){
  loading('My Leads');
  const r=route(),params=buildLeadParams(r,mode),d=await api(`/api/leads/summary?${params}`);
  const q=r.query.get('q')||'',classification=r.query.get('classification')||'',contact=r.query.get('contact')||'',stage=r.query.get('stage')||'',temperature=mode==='HOT'?'HOT':(r.query.get('temperature')||'');
  const tempFilters=[['','ALL'],['HOT','🔥 HOT'],['WARM','🟠 WARM'],['DEVELOPING','🟡 DEVELOPING'],['LOW','🔵 LOW'],['COLD','❄ COLD']];
  const html=`<div class="page"><div class="page-head"><div><h2>My Leads</h2></div><button class="btn primary" id="new-lead">＋ Create Lead</button></div>
  <div class="lead-level-filters">${tempFilters.map(([v,t])=>`<button class="level-filter ${temperature===v||(!temperature&&!v)?'active':''}" data-temp="${v}">${t}</button>`).join('')}</div>
  <div class="filter-bar staff-filters"><input id="lead-search" value="${esc(q)}" placeholder="Search ID, customer, company, phone, email, product, model, city..."><select id="lead-class"><option value="">Live + Historical</option><option value="LIVE" ${classification==='LIVE'?'selected':''}>Live Leads</option><option value="HISTORICAL" ${classification==='HISTORICAL'?'selected':''}>Historical Import</option></select><select id="lead-contact"><option value="">All Contact Status</option><option value="UNCONTACTED" ${contact==='UNCONTACTED'?'selected':''}>Not Contacted</option><option value="CONTACTED" ${contact==='CONTACTED'?'selected':''}>Contacted</option></select><select id="lead-stage"><option value="">All Stages</option>${STAGES.map(s=>`<option ${stage===s?'selected':''}>${s}</option>`).join('')}</select></div>
  <section class="card lead-table-card"><div class="list-meta"><b>${d.total.toLocaleString('en-IN')} leads</b><span>Page ${d.page} of ${d.pages}</span></div>${d.rows.length?compactLeadTable(d.rows):emptyState(temperature?`No ${label(temperature)} Leads`:'No leads found',temperature?'No current records match this lead level.':'No records match this view.','<button class="btn primary" id="empty-create-lead">Create Lead</button>')}</section>
  <div class="pager"><button class="btn" id="prev-page">← Previous</button><span>${d.page} / ${d.pages}</span><button class="btn" id="next-page">Next →</button></div></div>`;
  app.innerHTML=shell(html,'My Leads');bindShell();bindLeadRows();$('#new-lead').onclick=openCreateLead;$('#empty-create-lead')?.addEventListener('click',openCreateLead);
  const buildUrl=(page=null,tempOverride=undefined)=>{const p=new URLSearchParams();const sv=$('#lead-search')?.value.trim()||q;if(sv)p.set('q',sv);const cl=$('#lead-class')?.value??classification;if(cl)p.set('classification',cl);const co=$('#lead-contact')?.value??contact;if(co)p.set('contact',co);const st=$('#lead-stage')?.value??stage;if(st)p.set('stage',st);const tv=tempOverride!==undefined?tempOverride:temperature;if(tv)p.set('temperature',tv);if(page&&page>1)p.set('page',String(page));return `#/leads${p.toString()?`?${p}`:''}`};
  $('#lead-search').oninput=debounce(()=>go(buildUrl(1)),300);for(const id of ['lead-class','lead-contact','lead-stage'])$('#'+id).onchange=()=>go(buildUrl(1));
  $$('.level-filter').forEach(b=>b.onclick=()=>go(buildUrl(1,b.dataset.temp)));
  $('#prev-page').onclick=()=>d.page<=1?toast('You are already on the first page.'):go(buildUrl(d.page-1));$('#next-page').onclick=()=>!d.has_more?toast('No more leads on the next page.'):go(buildUrl(d.page+1));
}
function guidedAccordion(title,hint,content){return `<details class="guided-accordion"><summary><div><b>${esc(title)}</b><small>${esc(hint)}</small></div><span>Open details</span></summary><div class="guided-accordion-body">${content}</div></details>`}
function stageNavigator(d){
  const progress=d.playbook_progress||{completed:0,skipped:0,total:12,percent:0,current_stage_no:1,current_stage_name:'Qualify Leads'};
  const shown=state.currentStep||Number(progress.current_stage_no||1);
  return `<section class="workflow-card guided-workflow"><div class="workflow-head"><div><small>12-STEP SALES PROCESS</small><h3>${progress.completed||0} of ${progress.total||12} complete${progress.skipped?` • ${progress.skipped} skipped`:''}</h3><p>Work one section at a time. Save & Next moves to the next sales step.</p></div><strong>${progress.percent||0}%</strong></div><div class="workflow-progress"><span style="width:${Math.max(0,Math.min(100,Number(progress.percent||0)))}%"></span></div><div class="stage-nav">${PLAYBOOK.map(([no,name,short])=>{const row=d.playbook?.find(x=>Number(x.stage_no)===no),st=row?.status||'PENDING';const cls=st==='COMPLETED'?'done':st==='SKIPPED'?'skipped':shown===no?'active':st==='BLOCKED'?'blocked':'pending';const icon=st==='COMPLETED'?'✓':st==='SKIPPED'?'—':no;const txt=st==='COMPLETED'?'Complete':st==='SKIPPED'?'Skipped':shown===no?'Current':'Pending';return `<button class="stage-chip ${cls}" data-stage-no="${no}" title="${esc(name)}"><i>${icon}</i><span>${esc(short)}</span><small>${txt}</small></button>`}).join('')}</div></section>`
}
function leadHeader(d){const l=d.lead,c=d.customer,r=d.requirements?.[0]||{};return `<section class="lead-hero"><div><div class="eyebrow">${classBadge(l.live_classification)} <span>${esc(l.source_type)}</span> ${l.possible_duplicate?'<span class="pill red">Possible Duplicate</span>':''}</div><h2>${esc(r.product_name||'Lead')}</h2><p><b>${esc(c.name)}</b>${c.company?` • ${esc(c.company)}`:''} • ${esc([c.city,c.state].filter(Boolean).join(', ')||'Location not available')}</p></div><div class="score-box">${temperatureBadge(l.temperature)}<strong>${l.purchase_probability}%</strong><span>Purchase Probability</span></div></section><div class="lead-metrics"><div><span>Quantity</span><b>${esc(r.quantity||'Not Available')}</b></div><div><span>Lead Age</span><b>${esc(ago(l.received_at))}</b></div><div><span>Priority</span><b>${esc(l.priority)}</b></div><div><span>Current Stage</span><b>${esc(label(l.pipeline_stage))}</b></div><div><span>Next Follow-Up</span><b>${esc(l.next_followup_at?fmtDate(l.next_followup_at):'Not Scheduled')}</b></div><div><span>Owner</span><b>${esc(l.owner_name||'Unassigned')}</b></div></div>`}
function buyerReqCard(d){const r=d.requirements?.[0]||{},l=d.lead;return `<section class="card"><div class="card-head"><div><h3>Buyer Requirements</h3><small>Confirmed customer facts only</small></div><button class="btn sm" id="edit-requirement">Edit</button></div><div class="info-grid">${kv('Product',r.product_name,'CONFIRMED')}${kv('Brand',r.requested_brand||r.preferred_brand,r.requested_brand?'CONFIRMED':'NEEDS VERIFICATION')}${kv('Model',r.requested_model,r.requested_model?'CONFIRMED':'NEEDS VERIFICATION')}${kv('Quantity',r.quantity,r.status?.quantity||'NEEDS VERIFICATION')}${kv('Application',r.application,r.application?'CONFIRMED':'NEEDS VERIFICATION')}${kv('Range',r.required_range,r.required_range?'CONFIRMED':'NEEDS VERIFICATION')}${kv('Accuracy',r.required_accuracy,r.required_accuracy?'CONFIRMED':'NEEDS VERIFICATION')}${kv('Budget',r.budget?fmtMoney(r.budget):null,l.budget_status)}${kv('Delivery Date',r.required_delivery_date?fmtDate(r.required_delivery_date,true):null,r.required_delivery_date?'CONFIRMED':'NEEDS VERIFICATION')}${kv('Catalogue',r.catalogue_required?'Requested':'Not requested',r.catalogue_required?'CONFIRMED':'NOT AVAILABLE')}</div>${d.discovery_questions?.length?`<div class="question-box"><div><b>Product-specific discovery questions</b><small>Use only relevant questions and save the answers into Buyer Requirements.</small></div><ul>${d.discovery_questions.map(q=>`<li>${esc(q)}</li>`).join('')}</ul><button class="btn sm" id="answer-questions">Save Answers</button></div>`:''}</section>`}
function kv(k,v,status=''){const cls=status?'field-status inferred':'';return `<div class="info-item"><label>${esc(k)}</label><div class="value">${esc(v??'Not Available')}</div>${status?`<div class="${cls}">${esc(label(status))}</div>`:''}</div>`}
function leadMatchesQuery(row,q=''){const s=String(q||'').trim().toLowerCase();if(!s)return true;return [row?.lead_code,row?.customer_name,row?.company,row?.product_name,row?.owner_name,row?.requested_model,row?.supplier].filter(Boolean).some(v=>String(v).toLowerCase().includes(s))}
function completedLead(row){return String(row?.form_status||'').toUpperCase()==='COMPLETED'||String(row?.work_status||'').toUpperCase()==='COMPLETED'}
function pendingLead(row){return !completedLead(row)}
function qualificationCard(d){const l=d.lead;const isVerified=Boolean(l.verified_at);return `<section class="card"><div class="card-head"><div><h3>Lead Quality</h3><small>AI preliminary score is separate from salesperson verification</small></div><button class="btn sm" id="verify-lead">${isVerified?'Edit Verification':'Verify Lead'}</button></div><div class="score-compare"><div><span>AI PRELIMINARY SCORE</span><b>${l.ai_score??0}%</b>${temperatureBadge(tempFor(Number(l.ai_score||0)))}</div><div><span>MARKETING VERIFIED SCORE</span><b>${isVerified&&l.verified_score!==null&&l.verified_score!==undefined?`${l.verified_score}%`:'Not Verified'}</b>${isVerified&&l.verified_temperature?temperatureBadge(l.verified_temperature):'<span class="pill slate">Pending</span>'}${isVerified?`<small class="subline">${esc(l.verified_by||'Salesperson')} • ${esc(fmtDate(l.verified_at))}</small>`:''}</div></div><div class="qualification-grid">${kv('Need',l.requirement_status)}${kv('Budget',l.budget_status)}${kv('Urgency',l.urgency)}${kv('Authority',l.decision_maker)}${kv('Timeline',l.timeline)}${kv('Purchase Intent',l.purchase_intent)}</div></section>`}
function tempFor(n){return n>=90?'VERY HOT':n>=75?'HOT':n>=55?'WARM':n>=35?'DEVELOPING':n>=15?'LOW':'COLD'}
function nextActionCard(d){const n=d.next_best_action||{};return `<section class="card next-action"><small>NEXT BEST ACTION</small><h3>${n.icon||'→'} ${esc(n.title||'Review lead')}</h3><p>${esc(n.reason||'')}</p>${n.question?`<blockquote>${esc(n.question)}</blockquote>`:''}</section>`}
function productIntelCard(d){const pis=d.product_intelligence||[];if(!pis.length)return `<section class="card">${emptyState('Product Intelligence unavailable','No product requirement is available yet.')}</section>`;return pis.map(pi=>{const b=pi.best_match,p=b?.product;const verified=pi.verification_status||'NEEDS VERIFICATION';return `<section class="card"><div class="card-head"><div><h3>Product Intelligence</h3><small>Requested: ${esc(pi.requirement?.product_name||'')}</small></div>${statusPill(pi.best_match?verified:'NEEDS VERIFICATION')}</div><div class="match-summary"><div><span>Best Internal Match</span><b>${esc(p?.name||'No verified internal product match')}</b><small>${esc([p?.brand,p?.model].filter(Boolean).join(' • '))}</small></div><div><span>Match Confidence</span><strong>${Number(b?.confidence||b?.score||0)}%</strong></div></div><div class="product-meta">${kv('Brand',p?.brand,verified)}${kv('Series',p?.series,verified)}${kv('Model',p?.model,verified)}${kv('Internal Product ID',p?.internal_code||p?.id,verified)}</div><h4>Specifications</h4><div class="spec-table"><div class="spec-head"><span>Specification</span><span>Value</span><span>Source</span><span>Status</span></div>${(pi.specs||[]).map(s=>`<div><b>${esc(s.spec_key)}</b><span>${esc(s.spec_value||'Not Available')}</span><small>${esc(s.source||'Not Available')} • ${Number(s.confidence||0)}%</small>${statusPill(s.verification_status||'NEEDS VERIFICATION')}</div>`).join('')}</div><div class="content-cols"><div><h4>Description</h4><p>${esc(pi.description||'')}</p></div><div><h4>Key Features</h4><ul>${(pi.features||[]).map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div><div><h4>Applications</h4><ul>${(pi.applications||[]).map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div></div>${pi.alternatives?.length?`<h4>Reasonable Alternatives</h4><div class="solution-grid">${pi.alternatives.map((a,i)=>`<div><span>${i===0?'ALTERNATIVE':i===1?'ECONOMY / OPTION':'PREMIUM / OPTION'}</span><b>${esc(a.product?.name||'')}</b><small>${esc([a.product?.brand,a.product?.model].filter(Boolean).join(' • '))}</small><strong>${Number(a.confidence||0)}% match</strong></div>`).join('')}</div>`:''}</section>`}).join('')}
function priceIntelCard(d){const p=d.price_intelligence||{},o=p.online_price||{},base=o.original_price||null;return `<section class="card"><div class="card-head"><div><h3>Price Intelligence</h3><small>Exact online/company price evidence</small></div>${statusPill(p.status||'NOT AVAILABLE')}</div>${(p.status==='AVAILABLE'||p.status==='ONLINE PRICE FOUND')?`<div class="price-grid">${kv('Original / Online',fmtMoney(base),o.confidence?'CONFIRMED':p.reliability)}${kv('Selling Price',fmtMoney(p.suggested_selling),p.reliability)}${kv('GST',p.gst_percent!==null&&p.gst_percent!==undefined?`${p.gst_percent}%`:null,'CONFIRMED')}${kv('Margin',p.margin_percent!==null&&p.margin_percent!==undefined?`${p.margin_percent}%`:null,p.margin_percent!==null?'CONFIRMED':'NOT AVAILABLE')}${kv('Price Date',p.price_date?fmtDate(p.price_date,true):null,p.reliability)}${kv('Supplier',p.supplier,p.supplier?'CONFIRMED':'NOT AVAILABLE')}${kv('Stock',p.stock_status,p.stock_status?'CONFIRMED':'NOT AVAILABLE')}${kv('Reliability',p.reliability,p.reliability)}</div>`:`<div class="verification-required"><b>NEEDS PRICE VERIFICATION</b><p>${esc(p.online_skip_reason||'No trustworthy exact-product price is available. The CRM will not guess a price.')}</p></div>`}<div class="actions"><button class="btn" id="verify-price">${p.status==='AVAILABLE'?'Edit / Verify Price':'Verify Price'}</button><button class="btn primary" id="use-quote">Use for Quotation</button></div></section>`}

function quotationUploadCard(d){const rows=d.quotation_uploads||[];return `<section class="card"><div class="card-head"><div><h3>Quotation</h3><small>Upload the quotation already prepared by your company. CRM quotation generation is disabled.</small></div><button class="btn primary sm" id="new-quote-upload">Upload Existing Quotation</button></div>${rows.length?`<div class="quote-list">${rows.map(q=>`<div><div><b>${esc(q.quotation_no||q.file_name)}</b><small>${esc(fmtDate(q.created_at))} • ${esc(q.file_name)}</small></div>${statusPill(q.status||'UPLOADED')}<strong>${fmtMoney(q.total)}</strong><div class="actions"><a class="btn sm" href="${esc(authFileUrl(q.file_url))}" target="_blank">Open File</a></div></div>`).join('')}</div>`:emptyState('No quotation uploaded yet','Upload your existing quotation PDF or document for this enquiry.')}</section>`}
function objectionCard(d){return `<section class="card"><div class="card-head"><div><h3>Objections</h3><small>Customer concern → response → resolution</small></div><button class="btn sm" id="add-objection">＋ Objection</button></div>${d.objections?.length?`<div class="objection-list">${d.objections.map(o=>`<div><div><b>${esc(o.category||o.objection)}</b>${statusPill(o.resolution_status)}</div><p>${esc(o.customer_comment||o.objection||'')}</p>${o.ai_suggested_response?`<small><b>Suggested:</b> ${esc(o.ai_suggested_response)}</small>`:''}<div class="actions"><button class="btn sm" data-objection="${o.id}">Update</button></div></div>`).join('')}</div>`:emptyState('No objections recorded','Add an objection only when the customer raises one.')}</section>`}
function followupActivity(d){return `<section class="card"><div class="card-head"><div><h3>Follow-Ups</h3><small>Next reminders and outcomes</small></div><button class="btn sm" id="schedule-followup">＋ Schedule</button></div>${d.followups?.length?`<div class="followup-list">${d.followups.map(f=>`<div class="${f.status==='PENDING'&&new Date(f.due_at)<new Date()?'overdue-item':''}"><div><b>${esc(fmtDate(f.due_at))}</b><small>${esc(f.method||'CALL')} • ${esc(f.reason||'')}</small></div>${statusPill(f.status)}${f.status==='PENDING'?`<button class="btn sm" data-complete-followup="${f.id}">Complete</button>`:''}</div>`).join('')}</div>`:emptyState('No follow-up scheduled','Schedule a follow-up to keep this opportunity active.')}</section>`}
function timelineCard(d){return `<section class="card"><div class="card-head"><h3>Activity Timeline</h3></div><div class="timeline">${d.activities?.length?d.activities.map(a=>`<div><i></i><div><b>${esc(a.title)}</b><small>${esc(label(a.activity_type))} • ${esc(fmtDate(a.created_at))}</small><p>${esc(a.detail||'')}</p></div></div>`).join(''):emptyState('No activity yet','Lead activity will appear automatically.')}</div></section>`}
function leadRight(d){const l=d.lead,c=d.customer;return `<aside class="lead-right">${nextActionCard(d)}<section class="card"><small>LEAD QUALITY</small><div class="right-score"><b>${l.purchase_probability}%</b>${temperatureBadge(l.temperature)}</div><div class="kv"><span>AI Score</span><b>${l.ai_score}%</b></div><div class="kv"><span>Verified Score</span><b>${l.verified_score===null?'Pending':`${l.verified_score}%`}</b></div></section><section class="card"><small>NEXT FOLLOW-UP</small><h3>${esc(l.next_followup_at?fmtDate(l.next_followup_at):'Not Scheduled')}</h3><p>${esc(l.next_followup_at?ago(l.next_followup_at):'Schedule the next contact.')}</p></section><section class="card"><small>CUSTOMER</small><h3>${esc(c.name)}</h3><p>${esc(c.company||'')}</p><div class="kv"><span>Phone</span><b>${esc(c.phone||'Not Available')}</b></div><div class="kv"><span>Email</span><b>${esc(c.email||'Not Available')}</b></div><a class="btn full" href="#/customer/${c.id}">Open Customer 360</a></section></aside>`}
function leadTabHtml(d,tab){if(tab==='product')return productIntelCard(d);if(tab==='commercial')return priceIntelCard(d)+quotationUploadCard(d)+objectionCard(d)+orderCard(d);if(tab==='activity')return followupActivity(d)+timelineCard(d);return buyerReqCard(d)+qualificationCard(d)}
function orderCard(d){const l=d.lead;const ready=l.requirement_status==='CONFIRMED'&&['PRICE VERIFIED','QUOTATION READY','QUOTATION SENT','NEGOTIATION','ORDER EXPECTED'].includes(l.pipeline_stage)&&(l.purchase_intent==='READY TO BUY'||l.purchase_probability>=75||l.pipeline_stage==='ORDER EXPECTED');return `<section class="card order-card"><div class="card-head"><div><h3>Ask for the Order</h3><small>Use only when the commercial opportunity is ready</small></div>${ready?'<span class="pill green">Customer may be ready</span>':'<span class="pill slate">Not ready yet</span>'}</div><blockquote>“Shall we proceed with the order?”</blockquote><div class="actions"><button class="btn primary" data-order="ORDER CONFIRMED">Order Confirmed</button><button class="btn" data-order="WAITING FOR PO">Waiting for PO</button><button class="btn" data-order="WAITING FOR APPROVAL">Waiting Approval</button><button class="btn" data-order="FOLLOW-UP REQUIRED">Follow-Up Required</button><button class="btn" data-order="NOT READY">Not Ready</button><button class="btn danger" data-order="LOST">Lost</button></div></section>`}


function marketTypeFor(d){const v=String(d.lead?.market_type_override||'').toUpperCase();if(['INDIA','EXPORT'].includes(v))return v;const raw=String(d.customer?.country||'').trim().toLowerCase(),c=raw.replace(/[^a-z0-9]/g,'');return !c||['in','ind','india','bharat'].includes(c)||raw.startsWith('india')?'INDIA':'EXPORT'}
function timeOnly(v){if(!v)return 'Not Available';const d=new Date(v);return Number.isFinite(d.getTime())?new Intl.DateTimeFormat('en-IN',{hour:'2-digit',minute:'2-digit'}).format(d):'Not Available'}
function requirementState(value,confirmed=false){if(confirmed||value===true||value===1)return 'CONFIRMED';if(value===false)return 'NOT AVAILABLE';return value!==null&&value!==undefined&&String(value).trim()!==''?'AI INFERRED':'NEEDS CONFIRMATION'}
function reqFact(name,value,status='NEEDS CONFIRMATION'){const shown=(value===null||value===undefined||value==='')?'Not Available':value;return `<div class="req-fact"><span>${esc(name)}</span><b>${esc(shown)}</b>${statusPill(status)}</div>`}
function guidedLeadHeader(d){const l=d.lead,c=d.customer,r=d.requirements?.[0]||{},where=[c.city,c.state,c.country].filter(Boolean).join(' • ')||'Location not available';return `<section class="guided-lead-header"><div class="guided-title"><small>LEAD SALES FORM • ${esc(l.lead_code)}</small><h1>${esc(r.product_name||'Lead')}</h1><p><b>${esc(c.name)}</b>${c.company?` • ${esc(c.company)}`:''}</p><p>${esc(where)}</p><div class="guided-badges">${classBadge(l.live_classification)} <span class="pill blue">${esc(l.source_type||'CRM')}</span><span class="pill ${marketTypeFor(d)==='INDIA'?'green':'blue'}">${marketTypeFor(d)}</span>${l.possible_duplicate?'<span class="pill red">Possible Duplicate</span>':''}</div></div><div class="guided-score">${temperatureBadge(l.temperature)}<strong>${Number(l.purchase_probability||0)}%</strong><span>Purchase Probability</span><div class="large-progress"><i style="width:${Number(l.purchase_probability||0)}%"></i></div><small>AI ${Number(l.ai_score||0)}% • Verified ${l.verified_score==null?'Pending':`${l.verified_score}%`}</small></div></section>`}
function guidedTopInformation(d){const l=d.lead,c=d.customer,r=d.requirements?.[0]||{};return `<section class="card guided-info"><div class="card-head"><div><h3>Lead & Customer Information</h3><small>Everything the salesperson needs before starting the 12-step process.</small></div><button class="btn" id="edit-profile">Edit</button></div><div class="guided-fact-grid">${reqFact('Product Name',r.product_name,'CONFIRMED')}${reqFact('Quantity',r.quantity?`${r.quantity} ${r.unit||'Piece'}`:null,requirementState(r.quantity,Boolean(r.quantity)))}${reqFact('Lead Received Date',fmtDate(l.received_at,true),'CONFIRMED')}${reqFact('Lead Received Time',timeOnly(l.received_at),'CONFIRMED')}${reqFact('Lead Age',ago(l.received_at),'CONFIRMED')}${reqFact('Customer Name',c.name,'CONFIRMED')}${reqFact('Company Name',c.company,requirementState(c.company))}${reqFact('Phone Number',c.phone,requirementState(c.phone))}${reqFact('Email',c.email,requirementState(c.email))}${reqFact('City',c.city,requirementState(c.city))}${reqFact('State',c.state,requirementState(c.state))}${reqFact('Country',c.country||'India',requirementState(c.country||'India',true))}${reqFact('India / Export',marketTypeFor(d),'CONFIRMED')}${reqFact('Source',l.source_type,'CONFIRMED')}${reqFact('Owner',l.owner_name||'Unassigned',requirementState(l.owner_name))}${reqFact('Next Follow-Up',l.next_followup_at?fmtDate(l.next_followup_at):'Not Scheduled',l.next_followup_at?'CONFIRMED':'NOT AVAILABLE')}</div></section>`}
function guidedBuyerRequirements(d){const r=d.requirements?.[0]||{},l=d.lead;const boolText=v=>Number(v)===1?'Yes':'Not Confirmed';return `<section class="card guided-requirements"><div class="card-head"><div><h3>Buyer Requirements</h3><small>Extracted from the original enquiry. Confirm only what the customer actually said.</small></div><button class="btn" id="edit-requirement">Edit</button></div><div class="guided-fact-grid requirement-grid">${reqFact('Product',r.product_name,'CONFIRMED')}${reqFact('Brand',r.requested_brand||r.preferred_brand,requirementState(r.requested_brand||r.preferred_brand))}${reqFact('Model',r.requested_model,requirementState(r.requested_model))}${reqFact('Quantity',r.quantity?`${r.quantity} ${r.unit||'Piece'}`:null,r.status?.quantity||requirementState(r.quantity))}${reqFact('Usage / Application',r.application,requirementState(r.application))}${reqFact('Required Range',r.required_range,requirementState(r.required_range))}${reqFact('Required Accuracy',r.required_accuracy,requirementState(r.required_accuracy))}${reqFact('Specification Requested',r.required_specification,requirementState(r.required_specification))}${reqFact('Accessories',r.requested_accessories,requirementState(r.requested_accessories))}${reqFact('Calibration Required',boolText(r.calibration_required),Number(r.calibration_required)===1?'CONFIRMED':'NEEDS CONFIRMATION')}${reqFact('Installation Required',boolText(r.installation_required),Number(r.installation_required)===1?'CONFIRMED':'NEEDS CONFIRMATION')}${reqFact('Catalogue Requested',Number(r.catalogue_required)===1?'Yes':'Not Confirmed',Number(r.catalogue_required)===1?'CONFIRMED':'NEEDS CONFIRMATION')}${reqFact('Delivery Location',r.delivery_location,requirementState(r.delivery_location))}${reqFact('Required Delivery Date',r.required_delivery_date?fmtDate(r.required_delivery_date,true):null,requirementState(r.required_delivery_date))}${reqFact('Budget',r.budget?fmtMoney(r.budget):null,l.budget_status==='CONFIRMED'?'CONFIRMED':l.budget_status==='NOT AVAILABLE'?'NOT AVAILABLE':'NEEDS CONFIRMATION')}${reqFact('Other Customer Notes',r.other_notes,requirementState(r.other_notes))}</div>${d.discovery_questions?.length?`<div class="question-box guided-question-box"><div><b>Questions still worth asking</b><small>Product-specific. Already confirmed information should not be asked again.</small></div><ul>${d.discovery_questions.slice(0,8).map(q=>`<li>${esc(q)}</li>`).join('')}</ul><button class="btn" id="answer-questions">Update Missing Answers</button></div>`:''}</section>`}
function guidedProductInformation(d){const pi=d.product_intelligence?.[0];if(!pi)return `<section class="card guided-product">${emptyState('Product information is being prepared','The requirement will appear here as soon as product analysis completes.')}</section>`;const b=pi.best_match,p=b?.product||{};return `<section class="card guided-product"><div class="card-head"><div><h3>Product Information</h3><small>${pi.best_match?`Best internal match • ${Number(b.confidence||b.score||0)}% confidence`:'No verified internal match yet'}</small></div>${statusPill(pi.best_match?(pi.verification_status||'NEEDS VERIFICATION'):'NEEDS VERIFICATION')}</div><div class="product-match-banner"><div><span>BEST INTERNAL MATCH</span><b>${esc(p.name||pi.requirement?.product_name||'Needs Verification')}</b><small>${esc([p.brand,p.model].filter(Boolean).join(' • '))}</small></div><strong>${Number(b?.confidence||b?.score||0)}%</strong></div><div class="product-order-block"><h4>SPECIFICATIONS</h4><div class="spec-table guided-specs"><div class="spec-head"><span>Specification</span><span>Value</span><span>Source</span><span>Status</span></div>${(pi.specs||[]).map(x=>`<div><b>${esc(x.spec_key)}</b><span>${esc(x.spec_value||'Not Available')}</span><small>${esc(x.source||'Not Available')} • ${Number(x.confidence||0)}%</small>${statusPill(x.verification_status||'NEEDS VERIFICATION')}</div>`).join('')}</div><h4>PRODUCT DESCRIPTION</h4><div class="technical-copy">${esc(pi.description||'Product description needs verification.')}</div><h4>KEY FEATURES</h4><ul class="feature-list">${(pi.features||[]).map(x=>`<li>${esc(x)}</li>`).join('')}</ul><h4>APPLICATIONS</h4><ul class="feature-list">${(pi.applications||[]).map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div>${pi.alternatives?.length?`<div class="solution-grid guided-solutions">${pi.alternatives.slice(0,3).map((a,i)=>`<div><span>${i===0?'ALTERNATIVE':i===1?'ECONOMY OPTION':'PREMIUM OPTION'}</span><b>${esc(a.product?.name||'')}</b><small>${esc([a.product?.brand,a.product?.model].filter(Boolean).join(' • '))}</small><strong>${Number(a.confidence||0)}% match</strong></div>`).join('')}</div>`:''}</section>`}
function guidedPriceInformation(d){const p=d.price_intelligence||{},pi=d.product_intelligence?.[0],match=Number(p.match_percent||pi?.best_match?.confidence||pi?.best_match?.score||0),o=p.online_price||{},latest=p.records?.[0]||{};const available=['AVAILABLE','ONLINE PRICE FOUND'].includes(p.status);return `<section class="card guided-price"><div class="card-head"><div><h3>Price Intelligence</h3><small>Exact product/model price first. Uncertain online prices are skipped, not guessed.</small></div>${statusPill(p.status||'NEEDS PRICE VERIFICATION')}</div>${available?`<div class="guided-fact-grid price-facts">${reqFact('Matched Product',p.matched_product||pi?.best_match?.product?.name||pi?.requirement?.product_name,'CONFIRMED')}${reqFact('Match Confidence',match?`${Math.round(match)}%`:null,match>=80?'CONFIRMED':'NEEDS VERIFICATION')}${reqFact('Original / Online Price',fmtMoney(o.original_price),o.original_price?'CONFIRMED':'NOT AVAILABLE')}${reqFact('Margin',p.margin_percent!==null&&p.margin_percent!==undefined?`${p.margin_percent}%`:null,requirementState(p.margin_percent))}${reqFact('Selling Price',fmtMoney(p.suggested_selling),'NEEDS VERIFICATION')}${reqFact('GST',p.gst_percent!==null&&p.gst_percent!==undefined?`${p.gst_percent}%`:null,requirementState(p.gst_percent))}${reqFact('Supplier',p.supplier,requirementState(p.supplier))}${reqFact('Price Date',p.price_date?fmtDate(p.price_date,true):null,p.reliability)}${reqFact('Stock',p.stock_status,requirementState(p.stock_status))}</div>`:`<div class="verification-required"><b>PRICE NOT AVAILABLE / NEEDS PRICE VERIFICATION</b><p>${esc(p.online_skip_reason||'No trustworthy exact-product price is available. ₹0 is never shown as a selling price.')}</p></div>`}<div class="actions price-actions"><button class="btn" id="verify-price">${available?'VERIFY / EDIT PRICE':'VERIFY PRICE'}</button><button class="btn" id="price-search-again">SEARCH AGAIN</button><button class="btn primary" id="use-quote">USE FOR QUOTATION</button></div>${latest.verified_by?`<p class="verification-line">✓ Price verified by ${esc(latest.verified_by)} • ${esc(fmtDate(latest.verified_at||latest.price_date))}</p>`:''}</section>`}

function chipOptions(name,labelText,options,current=''){return `<fieldset class="chip-field"><legend>${esc(labelText)}</legend><div class="choice-chips">${options.map(o=>{const val=Array.isArray(o)?o[0]:o,txt=Array.isArray(o)?o[1]:o;return `<label><input type="radio" name="${esc(name)}" value="${esc(val)}" ${String(val)===String(current)?'checked':''}><span>${esc(txt)}</span></label>`}).join('')}</div></fieldset>`}
function selectValue(form,name,fallback=''){return form?.querySelector(`[name="${name}"]:checked`)?.value??form?.querySelector(`[name="${name}"]`)?.value??fallback}
function currentPlaybookRow(d,no){return d.playbook?.find(x=>Number(x.stage_no)===Number(no))||{status:'PENDING',stage_data:{}}}
function stageSummary(row,no,d){const data=row?.stage_data||{};if(row?.status==='SKIPPED')return `<div class="completed-step skipped"><div><b>— ${no}. ${esc(PLAYBOOK[no-1][1])}</b><p>${esc(row.skip_reason||data.skip_reason||row.notes||'Skipped')}</p></div><button class="btn sm" data-stage-no="${no}">Edit</button></div>`;let summary=row?.notes||'Completed';if(no===1)summary=`${d.lead.temperature} • ${d.lead.purchase_probability}% • Budget ${label(d.lead.budget_status)} • Urgency ${label(d.lead.urgency)}`;if(no===2)summary=`${label(d.lead.response_status)} • ${d.lead.contact_attempts||0} contact attempt(s)`;if(no===3)summary=`Buyer requirement saved • ${d.requirements?.[0]?.application||'Application needs confirmation'}`;if(no===9){const uq=d.quotation_uploads?.[0];if(uq)summary=`${uq.quotation_no||uq.file_name} • ${label(uq.status||'UPLOADED')}`;}if(no===11)summary=d.lead.next_followup_at?`Next follow-up ${fmtDate(d.lead.next_followup_at)}`:'Follow-up reviewed';return `<div class="completed-step"><div><b>✓ ${no}. ${esc(PLAYBOOK[no-1][1])}</b><p>${esc(summary)}</p></div><button class="btn sm" data-stage-no="${no}">Edit</button></div>`}
function guidedStepBody(d,no){const row=currentPlaybookRow(d,no),x=row.stage_data||{},r=d.requirements?.[0]||{},l=d.lead,pi=d.product_intelligence?.[0],p=d.price_intelligence||{};if(no===1)return `<div class="step-intro"><h3>1. Qualify Lead</h3><p>Decide whether this is a genuine buyer, how serious the requirement is, and how quickly it may become an order.</p></div><form id="guided-step-form" class="guided-step-form">${chipOptions('requirement_status','Customer Requirement',[['CONFIRMED','Clear / Confirmed'],['NEEDS CLARIFICATION','Needs Clarification']],l.requirement_status)}${chipOptions('budget_status','Budget Status',[['CONFIRMED','Budget Confirmed'],['NOT AVAILABLE','Will Not Disclose'],['UNKNOWN','Unknown']],l.budget_status)}${chipOptions('budget_band','Budget Level',['ECONOMY','STANDARD','PREMIUM','SPECIFIC BRAND','UNKNOWN'],x.budget_band||'UNKNOWN')}${chipOptions('urgency_band','Purchase Urgency',['IMMEDIATE','1–2 WEEKS','1–3 MONTHS','FUTURE','UNKNOWN'],x.urgency_band||(l.urgency==='IMMEDIATE'?'IMMEDIATE':l.urgency==='THIS MONTH'?'1–2 WEEKS':l.urgency==='LATER'?'FUTURE':'UNKNOWN'))}${select('decision_role','Decision Maker Role',x.decision_role||'Unknown',['Purchase Executive','Procurement Manager','Lab Manager','QA/QC Manager','Production Manager','Project Engineer','Owner / Director','Consultant','Other','Unknown'])}${chipOptions('decision_authority','Decision Authority',['HIGH','MEDIUM','LOW','UNKNOWN'],x.decision_authority||'UNKNOWN')}${chipOptions('purchase_intent','Buying Intent',[['JUST ENQUIRY','Just Enquiry'],['INTERESTED','Interested'],['SERIOUS','Serious'],['READY TO BUY','Ready To Buy']],l.purchase_intent)}${chipOptions('commercial_potential','Commercial Potential',['HIGH','MEDIUM','LOW','UNKNOWN'],x.commercial_potential||'UNKNOWN')}${input('expected_value','Estimated Value',l.expected_value||'','number','min="0" step="1"')}${textarea('qualification_notes','Qualification Notes',x.qualification_notes||'',3)}</form><div class="score-preview"><div><span>AI SCORE</span><b>${Number(l.ai_score||0)}%</b></div><div><span>MARKETING VERIFIED SCORE</span><b>${l.verified_score==null?'Pending':`${l.verified_score}%`}</b></div><div><span>LEAD LEVEL</span>${temperatureBadge(l.temperature)}</div></div>`;
if(no===2){const sla=responseSla(l.received_at);return `<div class="step-intro"><h3>2. Follow Up Promptly</h3><p>Respond quickly and record only the result. The CRM tracks first response time and contact attempts automatically.</p></div><div class="sla-banner ${sla.cls}"><b>${sla.label}</b><span>${esc(sla.text)}</span></div><div class="contact-actions-large"><a class="btn primary" href="tel:${esc(d.customer.phone||'')}">☎ CALL</a><a class="btn" target="_blank" href="${d.customer.phone?`https://wa.me/${String(d.customer.phone).replace(/\D/g,'')}`:'#'}">◉ WHATSAPP</a><a class="btn" href="mailto:${esc(d.customer.email||'')}">✉ EMAIL</a></div><form id="guided-step-form" class="guided-step-form">${chipOptions('method','Contact Method',['CALL','WHATSAPP','EMAIL'],x.method||'CALL')}${chipOptions('outcome','Contact Result',['CONNECTED','NO ANSWER','BUSY','CALL LATER','WHATSAPP SENT','EMAIL SENT','WRONG NUMBER'],x.outcome||'CONNECTED')}${textarea('detail','Short Note',x.detail||'',3)}</form>`}
if(no===3){const questions=(d.discovery_questions||[]).filter(q=>{const z=q.toLowerCase();if(r.application&&z.includes('application'))return false;if(r.required_range&&z.includes('range'))return false;if(r.required_accuracy&&(z.includes('accuracy')||z.includes('resolution')))return false;if(r.budget&&z.includes('budget'))return false;if(r.required_delivery_date&&z.includes('delivery'))return false;if(r.quantity&&z.includes('quantity'))return false;return true});return `<div class="step-intro"><h3>3. Understand Customer Needs</h3><p>Ask only product-specific questions that are still unanswered. Saved answers feed Buyer Requirements, product matching and lead scoring.</p></div>${questions.length?`<div class="guided-question-list">${questions.map(q=>`<div>?</div><p>${esc(q)}</p>`).join('')}</div>`:'<div class="success-note">✓ Core requirement information is already available. Review and confirm below.</div>'}<form id="guided-step-form" class="guided-step-form">${input('application','Usage / Application',r.application||'')}${input('required_range','Required Range / Capacity',r.required_range||'')}${input('required_accuracy','Required Accuracy / Resolution',r.required_accuracy||'')}${input('requested_model','Preferred / Exact Model',r.requested_model||'')}${input('requested_brand','Preferred Brand',r.requested_brand||r.preferred_brand||'')}${input('quantity','Quantity',r.quantity||1,'number','min="0.01" step="0.01"')}${input('budget','Approximate Budget',r.budget||'','number','min="0"')}${input('required_delivery_date','Required Delivery Date',r.required_delivery_date?String(r.required_delivery_date).slice(0,10):'','date')}${textarea('required_specification','Technical Requirement',r.required_specification||'',3)}${textarea('other_notes','Customer Notes',r.other_notes||'',3)}</form>`}
if(no===4){const val=x.customer_value||generatedValue(d);return `<div class="step-intro"><h3>4. Present Clear Value</h3><p>The CRM prepares a short customer-specific value statement. Review it instead of writing from scratch.</p></div><form id="guided-step-form" class="guided-step-form">${textarea('customer_value','Value Statement',val,5)}</form><div class="actions"><button class="btn" id="copy-guided-value">COPY</button><a class="btn" href="mailto:${esc(d.customer.email||'')}?body=${encodeURIComponent(val)}">USE IN EMAIL</a><a class="btn" target="_blank" href="${d.customer.phone?`https://wa.me/${String(d.customer.phone).replace(/\D/g,'')}?text=${encodeURIComponent(val)}`:'#'}">USE IN WHATSAPP</a></div>`}
if(no===5){const best=pi?.best_match;const choices=[best,...(pi?.alternatives||[]).slice(0,3)].filter(Boolean);return `<div class="step-intro"><h3>5. Offer Solutions</h3><p>Recommend only technically reasonable matches from company product intelligence.</p></div>${choices.length?`<div class="solution-choice-grid">${choices.map((a,i)=>`<label><input type="radio" name="solution_pick" value="${esc(a.product?.name||'')}" ${i===0?'checked':''}><div><span>${i===0?'BEST MATCH':i===1?'ECONOMY OPTION':i===2?'STANDARD OPTION':'PREMIUM OPTION'}</span><b>${esc(a.product?.name||'')}</b><small>${esc([a.product?.brand,a.product?.model].filter(Boolean).join(' • '))}</small><strong>${Number(a.confidence||0)}% match</strong></div></label>`).join('')}</div>`:'<div class="verification-required"><b>NO VERIFIED ALTERNATIVE AVAILABLE</b><p>Do not recommend unrelated products.</p></div>'}<form id="guided-step-form" class="guided-step-form">${input('recommended_solution','Recommended Solution',x.recommended_solution||best?.product?.name||'')}${textarea('fit_reason','Why It Fits',x.fit_reason||generatedValue(d),3)}</form>`}
if(no===6){const q=d.quotations?.[0]||{};return `<div class="step-intro"><h3>6. Provide Detailed Information</h3><p>Reuse the product information already generated. Complete only missing commercial/detail items.</p></div><div class="detail-checklist"><div>✓ Specification</div><div>✓ Description</div><div>✓ Features</div><div>✓ Applications</div><div>${Number(r.catalogue_required)?'✓':'○'} Catalogue</div><div>${Number(r.technical_datasheet_required)?'✓':'○'} Datasheet</div><div>${p.status==='AVAILABLE'?'✓':'⚠'} Price</div><div>${p.gst_percent?'✓':'○'} GST</div><div>${p.lead_time?'✓':'○'} Delivery</div><div>${q.warranty?'✓':'○'} Warranty</div><div>${q.payment_terms?'✓':'○'} Terms</div></div><form id="guided-step-form" class="guided-step-form">${textarea('details_shared','Information Shared / Missing Detail',x.details_shared||'',3)}${input('documents','Catalogue / Datasheet Reference',x.documents||'')}</form><div class="actions"><button class="btn" id="copy-pack">COPY DETAILS</button><button class="btn" id="download-pack">DOWNLOAD PRODUCT DETAILS</button></div>`}
if(no===7)return `<div class="step-intro"><h3>7. Create Urgency</h3><p>Use genuine urgency only. Never fabricate stock, price validity, supplier revision or delivery.</p></div><form id="guided-step-form" class="guided-step-form">${chipOptions('urgency','Urgency',['IMMEDIATE','THIS WEEK','THIS MONTH','LATER','UNKNOWN'],x.urgency||l.urgency)}${select('urgency_type','Verified Urgency Type',x.urgency_type||'NONE',['NONE','Limited Stock','Price Validity','Supplier Price Validity','Delivery Slot','Tender Deadline','Customer Requested Date'])}${input('reason','Verified Reason',x.reason||'')}${input('source','Source / Evidence',x.source||'')}${input('valid_until','Valid Until',x.valid_until||'','date')}${textarea('stock_note','Stock / Delivery Note',x.stock_note||x.delivery_note||'',3)}<label class="check full"><input type="checkbox" name="no_verified_urgency" ${x.no_verified_urgency?'checked':''}><span>NO VERIFIED URGENCY AVAILABLE</span></label></form>`;
if(no===8){const objection=d.objections?.[0];return `<div class="step-intro"><h3>8. Address Objections</h3><p>Record the real customer concern. If there is none, select No and continue.</p></div><form id="guided-step-form" class="guided-step-form">${chipOptions('has_objection','Any Customer Concern?',[['NO','NO'],['YES','YES']],x.has_objection||(objection?'YES':'NO'))}<div class="objection-fields">${select('category','Concern Type',x.category||objection?.category||'PRICE TOO HIGH',['PRICE TOO HIGH','OTHER BRAND REQUIRED','DELIVERY TOO LONG','NEED TECHNICAL CONFIRMATION','BUDGET NOT APPROVED','MANAGEMENT APPROVAL','COMPETITOR CHEAPER','CALIBRATION REQUIRED','WARRANTY','PAYMENT TERMS','OTHER'])}${textarea('customer_comment','Customer Objection',x.customer_comment||objection?.customer_comment||'',3)}${textarea('salesperson_response','Response',x.salesperson_response||objection?.ai_suggested_response||objection?.salesperson_response||'',4)}${select('resolution_status','Resolution',x.resolution_status||objection?.resolution_status||'RESOLVED',['OPEN','RESPONDED','RESOLVED','LOST'])}</div></form>`}
if(no===9){const q=d.quotation_uploads?.[0];return `<div class="step-intro"><h3>9. Professional Proposal</h3><p>Upload the quotation already prepared by Nunes. This CRM no longer creates quotations.</p></div>${q?`<div class="quote-stage-summary"><div><span>Quotation</span><b>${esc(q.quotation_no||q.file_name)}</b></div><div><span>Status</span>${statusPill(q.status||'UPLOADED')}</div><div><span>Total</span><b>${fmtMoney(q.total)}</b></div><a class="btn" target="_blank" href="${esc(authFileUrl(q.file_url))}">OPEN FILE</a></div>`:'<div class="verification-required"><b>NO QUOTATION UPLOADED YET</b><p>Choose the existing company quotation file and upload it to this enquiry.</p></div>'}<div class="actions"><button class="btn primary" id="guided-upload-quote">UPLOAD EXISTING QUOTATION</button>${q?`<a class="btn" target="_blank" href="${esc(authFileUrl(q.file_url))}">VIEW QUOTATION</a>`:''}</div><form id="guided-step-form"><input type="hidden" name="quotation_upload_id" value="${q?.id||''}"></form>`}
if(no===10){const current=x.action||'';return `<div class="step-intro"><h3>10. Ask for the Order</h3><p>When the opportunity is ready, clearly ask for the order or proforma invoice.</p></div><div class="order-question">“Shall we proceed with the order?”</div><form id="guided-step-form">${chipOptions('action','Customer Status',[['ORDER CONFIRMED','READY TO ORDER'],['WAITING FOR PO','WAITING FOR PO'],['WAITING FOR APPROVAL','WAITING APPROVAL'],['NEGOTIATING','NEGOTIATING'],['NOT READY','NOT READY'],['LOST','LOST']],current)}</form>`}
if(no===11)return `<div class="step-intro"><h3>11. Follow Up</h3><p>Choose the next contact date and reason. Due follow-ups automatically appear on Today.</p></div><div class="shortcut-row">${['TODAY','TOMORROW','2 DAYS','3 DAYS','1 WEEK'].map(x=>`<button class="btn" data-fu-shortcut="${x}">${x}</button>`).join('')}</div><form id="guided-step-form" class="guided-step-form">${input('due_at','Next Follow-Up',x.due_at||followupDateShortcut('TOMORROW'),'datetime-local')}${chipOptions('method','Reason / Type',['CALL','QUOTATION','TECHNICAL','PRICE','PURCHASE ORDER','APPROVAL','PAYMENT','OTHER'],x.method||'CALL')}${select('priority','Priority',x.priority||l.priority||'NORMAL',['NORMAL','MEDIUM','HIGH'])}${textarea('followup_notes','Notes',x.followup_notes||'',3)}</form>`;
if(no===12){return `<div class="step-intro"><h3>12. Nurture Relationship</h3><p>If the order is not immediate, store the future opportunity against the customer so it is not lost.</p></div><div class="shortcut-row">${['30','60','90'].map(x=>`<button class="btn" data-nurture-days="${x}">${x} Days</button>`).join('')}</div><form id="guided-step-form" class="guided-step-form">${input('future_requirement','Future Requirement',x.future_requirement||d.nurture?.future_requirement||'')}${input('expected_purchase_month','Expected Purchase Month',x.expected_purchase_month||d.nurture?.expected_purchase_month||'','month')}${input('products_of_interest','Product Interest',x.products_of_interest||d.nurture?.products_of_interest||r.product_name||'')}${input('preferred_brands','Preferred Brands',x.preferred_brands||d.nurture?.preferred_brands||r.requested_brand||'')}${input('future_followup_at','Next Contact',x.future_followup_at||(d.nurture?.next_relationship_followup_at?localDateTimeValue(d.nurture.next_relationship_followup_at):''),'datetime-local')}${textarea('relationship_notes','Relationship Notes',x.relationship_notes||d.nurture?.notes||'',3)}</form>`}return ''}
function guidedCurrentStep(d,no){const row=currentPlaybookRow(d,no);return `<section class="card guided-current-step" id="current-sales-step"><div class="current-step-head"><div><small>CURRENT SALES STEP</small><h2>${no}. ${esc(PLAYBOOK[no-1][1])}</h2></div>${statusPill(row.status||'ACTIVE')}</div><div class="current-step-body">${guidedStepBody(d,no)}</div><div class="guided-step-footer"><button class="btn" id="guided-back">← BACK</button><div><button class="btn" id="guided-skip">SKIP</button><button class="btn" id="guided-save">SAVE</button><button class="btn primary" id="guided-save-next">SAVE & NEXT →</button></div></div></section>`}
function completedStepSummaries(d,current){const rows=(d.playbook||[]).filter(x=>['COMPLETED','SKIPPED'].includes(x.status)&&Number(x.stage_no)!==Number(current));return rows.length?`<section class="completed-steps"><h3>Completed Sections</h3>${rows.map(r=>stageSummary(r,Number(r.stage_no),d)).join('')}</section>`:''}
function collectGuidedData(no,d){const f=$('#guided-step-form');const data=f?formData(f):{};if(f)$$('input[type="checkbox"]',f).forEach(x=>data[x.name]=x.checked);if(no===5){const pick=document.querySelector('[name="solution_pick"]:checked');if(pick&&!data.recommended_solution)data.recommended_solution=pick.value}return data}
function qualificationPayload(data,d){const urg={'IMMEDIATE':'IMMEDIATE','1–2 WEEKS':'THIS MONTH','1–3 MONTHS':'LATER','FUTURE':'LATER','UNKNOWN':'UNKNOWN'};const role=String(data.decision_role||'Unknown');return {requirement_status:data.requirement_status||d.lead.requirement_status,budget_status:data.budget_status||d.lead.budget_status,urgency:urg[data.urgency_band]||d.lead.urgency,decision_maker:role&&role!=='Unknown'?'YES':'UNKNOWN',purchase_intent:data.purchase_intent||d.lead.purchase_intent,timeline:urg[data.urgency_band]||d.lead.timeline,expected_value:data.expected_value||d.lead.expected_value||null}}
async function saveGuidedDraft(id,no,d){const row=currentPlaybookRow(d,no);if(['COMPLETED','SKIPPED'].includes(row.status))return;const data=collectGuidedData(no,d);await api(`/api/leads/${id}/playbook/${no}`,{method:'PATCH',body:JSON.stringify({status:'ACTIVE',data,notes:'Auto-saved guided form draft'})})}
async function completeGuidedStep(id,no,d){const data=collectGuidedData(no,d);if(no===1){await api(`/api/leads/${id}/qualification`,{method:'PATCH',body:JSON.stringify(qualificationPayload(data,d))})}
  if(no===3&&d.requirements?.[0]){await api(`/api/leads/${id}/requirements/${d.requirements[0].id}`,{method:'PATCH',body:JSON.stringify(data)})}
  if(no===8&&String(data.has_objection||'NO')==='YES'){if(!String(data.customer_comment||'').trim())throw new Error('Enter the customer concern, or select NO.');await api(`/api/leads/${id}/objections`,{method:'POST',body:JSON.stringify({category:data.category,customer_comment:data.customer_comment,salesperson_response:data.salesperson_response,resolution_status:data.resolution_status||'RESOLVED'})})}
  if(no===9&&!d.quotation_uploads?.length)throw new Error('Upload the existing quotation first, or use Skip with a reason.');
  if(no===10){if(!data.action)throw new Error('Select the customer status.');if(data.action==='LOST'){openOrderAction(id,'LOST',d);return false}await api(`/api/leads/${id}/outcome`,{method:'POST',body:JSON.stringify({action:data.action})})}
  await api(`/api/leads/${id}/playbook/${no}`,{method:'PATCH',body:JSON.stringify({status:'COMPLETED',data,notes:`Step ${no} completed from guided sales form`})});return true}
function bindGuidedLead(id,d,current){$$('[data-stage-no]').forEach(b=>b.onclick=()=>{state.currentStep=Number(b.dataset.stageNo);renderLead(id).then(()=>setTimeout(()=>$('#current-sales-step')?.scrollIntoView({behavior:'smooth',block:'start'}),20))});$('#edit-profile')?.addEventListener('click',()=>openProfile(id,d));$('#edit-requirement')?.addEventListener('click',()=>openRequirement(id,d));$('#answer-questions')?.addEventListener('click',()=>{state.currentStep=3;renderLead(id)});$('#verify-price')?.addEventListener('click',()=>openPrice(id,d));$('#price-search-again')?.addEventListener('click',async()=>{try{await api(`/api/leads/${id}/analyze`,{method:'POST',body:JSON.stringify({force_price_refresh:true,price_only:true})});toast('Price search refreshed');renderLead(id)}catch(e){toast(e.message,'error')}});$('#use-quote')?.addEventListener('click',()=>{state.currentStep=9;renderLead(id)});$('#guided-upload-quote')?.addEventListener('click',()=>openQuotationUpload(id,d));$('#quote-action')?.addEventListener('click',()=>openQuotationUpload(id,d));$('#follow-action')?.addEventListener('click',()=>{state.currentStep=11;renderLead(id)});$('#note-action')?.addEventListener('click',()=>openNote(id));$('#edit-requirement')?.addEventListener('click',()=>openRequirement(id,d));$('#copy-guided-value')?.addEventListener('click',()=>navigator.clipboard.writeText($('#guided-step-form [name="customer_value"]')?.value||'').then(()=>toast('Copied')));if(current===6){const pack=buildInfoPack(d);$('#copy-pack')?.addEventListener('click',()=>navigator.clipboard.writeText(pack).then(()=>toast('Copied')));$('#download-pack')?.addEventListener('click',()=>downloadText(`${d.requirements?.[0]?.product_name||'product'}-details.txt`,pack))}$$('[data-fu-shortcut]').forEach(b=>b.onclick=()=>{const x=$('#guided-step-form [name="due_at"]');if(x)x.value=followupDateShortcut(b.dataset.fuShortcut)});$$('[data-nurture-days]').forEach(b=>b.onclick=()=>{const dt=new Date();dt.setDate(dt.getDate()+Number(b.dataset.nurtureDays));dt.setHours(10,0,0,0);const x=$('#guided-step-form [name="future_followup_at"]');if(x)x.value=localDateTimeValue(dt)});const form=$('#guided-step-form');if(form&& !['COMPLETED','SKIPPED'].includes(currentPlaybookRow(d,current).status)){form.onchange=debounce(()=>saveGuidedDraft(id,current,d).catch(()=>{}),450)}$('#guided-back')?.addEventListener('click',()=>{if(current<=1){toast('You are already on the first sales step.');return;}state.currentStep=current-1;renderLead(id)});$('#guided-save')?.addEventListener('click',async()=>{try{await saveGuidedDraft(id,current,d);toast('Saved. You can continue later.')}catch(e){toast(e.message,'error')}});$('#guided-save-next')?.addEventListener('click',async()=>{try{const ok=await completeGuidedStep(id,current,d);if(ok===false)return;state.currentStep=Math.min(12,current+1);toast(`Step ${current} saved`);renderLead(id)}catch(e){toast(e.message,'error')}});$('#guided-skip')?.addEventListener('click',()=>openSkipStep(id,current,d));$$('[data-contact-method]').forEach(a=>a.onclick=()=>setTimeout(()=>openContactOutcome(id,a.dataset.contactMethod),100))}
function openSkipStep(id,no,d){modal(`Skip Step ${no}`,`<div class="stage-help"><b>A reason is required.</b><p>Skipping keeps the employee moving without pretending the information was completed.</p></div><form id="skip-form">${textarea('reason','Reason for Skip','',4)}</form>`,`<button class="btn" data-cancel>Cancel</button><button class="btn primary" id="skip-save">Skip & Continue</button>`);$('[data-cancel]').onclick=closeModal;$('#skip-save').onclick=async()=>{try{const reason=$('#skip-form [name="reason"]').value.trim();if(!reason)throw new Error('Skip reason is required.');await api(`/api/leads/${id}/playbook/${no}`,{method:'PATCH',body:JSON.stringify({status:'SKIPPED',skip_reason:reason,notes:reason})});closeModal();state.currentStep=Math.min(12,no+1);toast(`Step ${no} skipped with reason`);renderLead(id)}catch(e){toast(e.message,'error')}}}
function openProfile(id,d){const c=d.customer;modal('Edit Lead & Customer Information',`<form id="profile-form" class="form-grid">${input('name','Customer Name',c.name||'')}${input('company','Company Name',c.company||'')}${input('phone','Phone Number',c.phone||'')}${input('email','Email',c.email||'','email')}${input('city','City',c.city||'')}${input('state','State',c.state||'')}${input('country','Country',c.country||'India')}${select('market_type_override','India / Export',d.lead.market_type_override||marketTypeFor(d),['INDIA','EXPORT'])}</form>`,`<button class="btn" data-cancel>Cancel</button><button class="btn primary" id="profile-save">Save</button>`);$('[data-cancel]').onclick=closeModal;$('#profile-save').onclick=async()=>{try{const b=formData($('#profile-form'));const market=b.market_type_override;delete b.market_type_override;await api(`/api/leads/${id}/profile`,{method:'PATCH',body:JSON.stringify({customer:b,market_type_override:market})});closeModal();toast('Lead/customer information updated');renderLead(id)}catch(e){toast(e.message,'error')}}}
function openNote(id){modal('Add Note',`<form id="note-form">${textarea('detail','Note','',5)}</form>`,`<button class="btn" data-cancel>Cancel</button><button class="btn primary" id="note-save">Save Note</button>`);$('[data-cancel]').onclick=closeModal;$('#note-save').onclick=async()=>{try{const detail=$('#note-form [name="detail"]').value.trim();if(!detail)throw new Error('Enter a note.');await api(`/api/leads/${id}/activity`,{method:'POST',body:JSON.stringify({type:'NOTE',title:'Sales note added',detail})});closeModal();toast('Note saved');renderLead(id)}catch(e){toast(e.message,'error')}}}
function openContactOutcome(id,method='CALL'){modal('Contact Result',`<form id="contact-result" class="form-grid">${select('outcome','Contact Result','CONNECTED',['CONNECTED','NO ANSWER','BUSY','CALL LATER','WHATSAPP SENT','EMAIL SENT','WRONG NUMBER'])}${textarea('detail','Short Note','',3)}</form>`,`<button class="btn" data-cancel>Cancel</button><button class="btn primary" id="contact-save">Save Result</button>`);$('[data-cancel]').onclick=closeModal;$('#contact-save').onclick=async()=>{try{const b=formData($('#contact-result'));b.type='CONTACT';b.method=method;await api(`/api/leads/${id}/activity`,{method:'POST',body:JSON.stringify(b)});closeModal();toast('Contact result saved');state.currentStep=Math.max(2,state.currentStep||2);renderLead(id)}catch(e){toast(e.message,'error')}}}
async function renderLeadGuidedLegacy(id){
  const switchingLead=Number(state.currentLeadId)!==Number(id);state.currentLeadId=Number(id);if(switchingLead)state.currentStep=null;
  loading('Lead Sales Form');const d=await api(`/api/leads/${id}`);state.lead=d;const progress=d.playbook_progress||{};if(!state.currentStep||state.currentStep<1||state.currentStep>12)state.currentStep=Number(progress.current_stage_no||1);const current=state.currentStep,c=d.customer;
  const html=`<div class="page guided-lead-page">${guidedLeadHeader(d)}<div class="sticky-actions guided-actions"><a class="btn" href="tel:${esc(c.phone||'')}" data-contact-method="CALL">☎ Call</a><a class="btn" target="_blank" href="${c.phone?`https://wa.me/${String(c.phone).replace(/\D/g,'')}`:'#'}" data-contact-method="WHATSAPP">◉ WhatsApp</a><a class="btn" href="mailto:${esc(c.email||'')}" data-contact-method="EMAIL">✉ Email</a><button class="btn" id="quote-action">▧ Quote</button><button class="btn" id="follow-action">◷ Follow-Up</button><button class="btn" id="note-action">✎ Add Note</button><a class="btn" href="#/customer/${c.id}">Customer History</a></div>${stageNavigator(d)}${guidedTopInformation(d)}<div class="guided-reference-stack">${guidedAccordion('Buyer Requirements','Confirmed customer facts and missing information',guidedBuyerRequirements(d))}${guidedAccordion('Product Information','Specifications → Description → Key Features → Applications',guidedProductInformation(d))}${guidedAccordion('Price Intelligence','Company price history, source and verification',guidedPriceInformation(d))}</div>${completedStepSummaries(d,current)}${guidedCurrentStep(d,current)}<section class="card guided-next-action">${nextActionCard(d)}</section></div>`;
  app.innerHTML=shell(html,'Lead Sales Form');bindShell();bindGuidedLead(id,d,current)
}
function bindLeadActions(id,d){bindGuidedLead(id,d,state.currentStep||Number(d.playbook_progress?.current_stage_no||1));$('#verify-lead')?.addEventListener('click',()=>openQualification(id,d));$('#new-quote-upload')?.addEventListener('click',()=>openQuotationUpload(id,d));$('#add-objection')?.addEventListener('click',()=>openObjection(id));$('#schedule-followup')?.addEventListener('click',()=>openFollowup(id,d));$$('[data-quote-email]').forEach(b=>b.onclick=async e=>{e.stopPropagation();if(!beginButtonAction(b,'Opening…'))return;const win=window.open('about:blank','_blank');try{const x=await api(`/api/quotations/${b.dataset.quoteEmail}/email`,{method:'POST',body:'{}'});openPreparedPersonalMessage(win,x,'Quotation opened in your personal Gmail.');}catch(err){if(win)win.close();toast(err.message,'error')}finally{endButtonAction(b,'Mail')}});}
function openRequirement(id,d,questions=false){const r=d.requirements?.[0];if(!r)return;modal(questions?'Update Missing Buyer Answers':'Edit Buyer Requirements',`<form id="req-form" class="form-grid">${input('product_name','Product',r.product_name)}${input('requested_brand','Brand',r.requested_brand||'')}${input('requested_model','Model',r.requested_model||'')}${input('quantity','Quantity',r.quantity||1,'number','step="0.01" min="0.01"')}${input('application','Usage / Application',r.application||'')}${input('required_range','Required Range / Capacity',r.required_range||'')}${input('required_accuracy','Required Accuracy / Resolution',r.required_accuracy||'')}${textarea('required_specification','Specification Requested',r.required_specification||'',3)}${input('requested_accessories','Accessories',r.requested_accessories||'')}${input('requested_certification','Certification',r.requested_certification||'')}${select('calibration_required','Calibration Required',String(Number(r.calibration_required)||0),[['0','Not Confirmed'],['1','Yes']])}${select('installation_required','Installation Required',String(Number(r.installation_required)||0),[['0','Not Confirmed'],['1','Yes']])}${select('catalogue_required','Catalogue Requested',String(Number(r.catalogue_required)||0),[['0','Not Confirmed'],['1','Yes']])}${select('technical_datasheet_required','Datasheet Requested',String(Number(r.technical_datasheet_required)||0),[['0','Not Confirmed'],['1','Yes']])}${input('delivery_location','Delivery Location',r.delivery_location||'')}${input('required_delivery_date','Required Delivery Date',r.required_delivery_date?String(r.required_delivery_date).slice(0,10):'','date')}${input('budget','Approximate Budget',r.budget||'','number','min="0"')}${textarea('requested_features','Required Features / Communication',r.requested_features||'',2)}${textarea('other_notes','Other Customer Notes',r.other_notes||'',3)}</form>${questions?`<div class="question-box modal-q"><b>Product-specific questions</b><ul>${(d.discovery_questions||[]).map(q=>`<li>${esc(q)}</li>`).join('')}</ul></div>`:''}`,`<button class="btn" data-cancel>Cancel</button><button class="btn primary" id="req-save">Save & Recalculate</button>`);$('[data-cancel]').onclick=closeModal;$('#req-save').onclick=async()=>{try{const b=formData($('#req-form'));await api(`/api/leads/${id}/requirements/${r.id}`,{method:'PATCH',body:JSON.stringify(b)});closeModal();toast('Buyer requirements saved; product, price and lead score recalculating');setTimeout(()=>renderLead(id),180)}catch(e){toast(e.message,'error')}}}
function openQualification(id,d){const l=d.lead;modal('1. Qualify Leads — Marketing Verification',`<div class="stage-help"><b>Verify the real buying situation.</b><p>Confirm Need, Budget, Urgency, Authority, Timeline and Purchase Intent. Saving recalculates AI/verified probability, temperature, priority and Next Best Action.</p></div><form id="qual-form" class="form-grid">${select('requirement_status','Need',l.requirement_status,['NEEDS CLARIFICATION','CONFIRMED'])}${select('budget_status','Budget',l.budget_status,['UNKNOWN','CONFIRMED','NOT AVAILABLE'])}${select('urgency','Urgency',l.urgency,['UNKNOWN','IMMEDIATE','THIS WEEK','THIS MONTH','LATER'])}${select('decision_maker','Decision Maker',l.decision_maker,['UNKNOWN','YES','NO'])}${select('purchase_intent','Purchase Intent',l.purchase_intent,['JUST ENQUIRY','INTERESTED','SERIOUS','READY TO BUY'])}${select('timeline','Expected Purchase Date',l.timeline,['UNKNOWN','IMMEDIATE','THIS WEEK','THIS MONTH','LATER'])}${input('verified_score','Marketing Verified Score',l.verified_at?(l.verified_score??''):'','number','min="0" max="100"')}${select('manual_override','Salesperson Temperature Override',l.manual_override||'',[['','No Override'],'COLD','LOW','DEVELOPING','WARM','HOT','VERY HOT'])}${textarea('manual_override_reason','Reason for Override',l.manual_override_reason||'',3)}</form><p class="form-note">Changes are audit logged with previous value, new value, user and time.</p>`,`<button class="btn" data-cancel>Cancel</button><button class="btn primary" id="qual-save">Save Verification</button>`);$('[data-cancel]').onclick=closeModal;$('#qual-save').onclick=async()=>{try{const b=formData($('#qual-form'));if(b.verified_score==='')delete b.verified_score;await api(`/api/leads/${id}/qualification`,{method:'PATCH',body:JSON.stringify(b)});closeModal();toast('Qualification verified and score recalculated');renderLead(id,state.leadTab)}catch(e){toast(e.message,'error')}}}
function localDateTimeValue(date){const d=new Date(date);d.setMinutes(d.getMinutes()-d.getTimezoneOffset());return d.toISOString().slice(0,16)}
function followupDateShortcut(kind){const d=new Date();if(kind==='TODAY')d.setHours(17,0,0,0);if(kind==='TOMORROW'){d.setDate(d.getDate()+1);d.setHours(10,0,0,0)}if(kind==='2 DAYS'){d.setDate(d.getDate()+2);d.setHours(10,0,0,0)}if(kind==='3 DAYS'){d.setDate(d.getDate()+3);d.setHours(10,0,0,0)}if(kind==='1 WEEK'){d.setDate(d.getDate()+7);d.setHours(10,0,0,0)}return localDateTimeValue(d)}
function openFollowup(id,d){modal('Schedule Follow-Up',`<div class="shortcut-row">${['TODAY','TOMORROW','2 DAYS','3 DAYS','1 WEEK'].map(x=>`<button class="btn sm" data-shortcut="${x}">${x}</button>`).join('')}</div><form id="fu-form" class="form-grid">${input('due_at','Date & Time',followupDateShortcut('TOMORROW'),'datetime-local')}${select('method','Type','CALL',['CALL','WHATSAPP','EMAIL','QUOTATION','PRICE','TECHNICAL','PAYMENT','PURCHASE ORDER','OTHER'])}${select('priority','Priority',d.lead.priority||'NORMAL',['NORMAL','MEDIUM','HIGH'])}${input('reason','Reason',d.next_best_action?.title||'Follow-up')}${textarea('notes','Notes','',3)}</form>`,`<button class="btn" data-cancel>Cancel</button><button class="btn primary" id="fu-save">Schedule</button>`);$('[data-cancel]').onclick=closeModal;$$('[data-shortcut]').forEach(b=>b.onclick=()=>$('#fu-form [name="due_at"]').value=followupDateShortcut(b.dataset.shortcut));$('#fu-save').onclick=async()=>{try{const b=formData($('#fu-form'));await api(`/api/leads/${id}/followups`,{method:'POST',body:JSON.stringify(b)});closeModal();toast('Follow-up scheduled');renderLead(id,state.leadTab)}catch(e){toast(e.message,'error')}}}
function openFollowupOutcome(followupId,leadId){modal('Follow-Up Outcome',`<form id="fu-out" class="form-grid">${select('outcome','Outcome','CUSTOMER INTERESTED',['CUSTOMER INTERESTED','ASKED TO CALL LATER','BUDGET PROBLEM','WAITING APPROVAL','NEED REVISED QUOTE','NEED TECHNICAL DETAILS','READY TO BUY','NO RESPONSE','LOST','OTHER'])}${textarea('notes','Notes','',3)}</form>`,`<button class="btn" data-cancel>Cancel</button><button class="btn primary" id="fu-out-save">Complete</button>`);$('[data-cancel]').onclick=closeModal;$('#fu-out-save').onclick=async()=>{try{await api(`/api/followups/${followupId}`,{method:'PATCH',body:JSON.stringify(formData($('#fu-out')))});closeModal();toast('Follow-up completed');renderLead(leadId,state.leadTab)}catch(e){toast(e.message,'error')}}}
function openPrice(id,d){const p=d.price_intelligence||{},online=p.online_price||{},policy=p.margin_policy||{},base=Number(online.original_price||0)||'',margin=Number.isFinite(Number(online.margin_percent))?Number(online.margin_percent):Number(policy.default||30),selling=Number(p.suggested_selling||online.suggested_selling_price||0)||'';modal('Marketing Price Verification',`<div class="stage-help"><b>Exact product price only.</b><p>Online price is used only when the exact product/model is sufficiently matched. If it is uncertain, the CRM skips it instead of guessing.</p></div><form id="price-form" class="form-grid">${input('online_reference_price','Original / Online Price',base,'number','min="0" step="0.01" readonly')}${input('online_margin_percent','Margin %',margin,'number','min="0" max="200" step="0.1"')}${input('selling_price','Selling Price',selling,'number','min="0" step="0.01"')}${input('gst_percent','GST %',p.gst_percent||18,'number','min="0"')}${input('price_date','Price Date',p.price_date?String(p.price_date).slice(0,10):new Date().toISOString().slice(0,10),'date')}${input('supplier','Supplier',p.supplier||online.supplier||'')}${input('stock_status','Stock',p.stock_status||online.stock_status||'')}</form>`,`<button class="btn" data-cancel>Cancel</button><button class="btn primary" id="price-save">PRICE CORRECT / VERIFY</button>`);$('[data-cancel]').onclick=closeModal;const recalc=()=>{const base=Number($('#price-form [name="online_reference_price"]')?.value||0),margin=Number($('#price-form [name="online_margin_percent"]')?.value||0),out=$('#price-form [name="selling_price"]');if(base>0&&Number.isFinite(margin)&&out)out.value=String(Math.round(base*(1+margin/100)*100)/100)};$('#price-form [name="online_margin_percent"]')?.addEventListener('input',recalc);$('#price-save').onclick=async()=>{try{const b=formData($('#price-form'));await api(`/api/leads/${id}/price`,{method:'POST',body:JSON.stringify(b)});closeModal();toast('Price verified with user/date/time');renderLead(id)}catch(e){toast(e.message,'error')}}}

function openQuotationUpload(id,d){const latest=d.quotation_uploads?.[0]||{},c=d.customer||{};modal('Upload Existing Quotation',`<div class="quote-customer"><b>${esc(c.name||'Customer')}</b><span>${esc(c.company||'')} • ${esc(d.requirements?.[0]?.product_name||'')}</span></div><form id="quote-upload-form" class="form-grid"><label class="field full"><span>Quotation File</span><input name="quotation_file" type="file" accept=".pdf,.jpg,.jpeg,.png,.webp,.doc,.docx,.xls,.xlsx" required><small>PDF, image, Word or Excel • maximum 8 MB</small></label>${input('quotation_no','Quotation Number',latest.quotation_no||'')}${input('total','Quotation Value',latest.total||'','number','min="0" step="0.01"')}${select('status','Status',latest.status||'UPLOADED',[['UPLOADED','Uploaded'],['READY','Ready'],['SENT','Sent'],['NEGOTIATION','Negotiation'],['ACCEPTED','Accepted'],['REJECTED','Rejected']])}${textarea('notes','Notes',latest.notes||'',3)}</form><div class="form-note">The original file is stored only on the MAIN SERVER data folder and is not pushed to GitHub.</div>`,`<button class="btn" data-cancel>Cancel</button><button class="btn primary" id="quote-upload-save">Upload Quotation</button>`);$('[data-cancel]').onclick=closeModal;$('#quote-upload-save').onclick=async()=>{const b=$('#quote-upload-save');if(!beginButtonAction(b,'Uploading…'))return;try{const f=$('#quote-upload-form'),file=f?.querySelector('[name="quotation_file"]')?.files?.[0];if(!file)throw new Error('Choose the existing quotation file.');if(file.size>8*1024*1024)throw new Error('Quotation file is too large. Maximum size is 8 MB.');const dataBase64=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result||'').split(',').pop()||'');reader.onerror=()=>reject(new Error('Could not read quotation file.'));reader.readAsDataURL(file)});const fd=formData(f);await api(`/api/leads/${id}/quotation-upload`,{method:'POST',body:JSON.stringify({file_name:file.name,mime_type:file.type||'application/octet-stream',data_base64:dataBase64,quotation_no:fd.quotation_no,status:fd.status,total:fd.total,notes:fd.notes})});closeModal();toast('Existing quotation uploaded');renderLead(id)}catch(e){toast(e.message,'error')}finally{if(b&&document.body.contains(b))endButtonAction(b,'Upload Quotation')}}}
function openObjection(id){const cats=['PRICE TOO HIGH','OTHER BRAND REQUIRED','DELIVERY TOO LONG','NEED TECHNICAL CONFIRMATION','BUDGET NOT APPROVED','MANAGEMENT APPROVAL','COMPETITOR CHEAPER','CALIBRATION REQUIRED','WARRANTY','PAYMENT TERMS','OTHER'];modal('Record Objection',`<form id="obj-form" class="form-grid">${select('category','Category','PRICE TOO HIGH',cats)}${textarea('customer_comment','Customer Objection','',3)}${textarea('salesperson_notes','Salesperson Notes','',3)}${select('resolution_status','Resolution','OPEN',['OPEN','RESPONDED','RESOLVED','LOST'])}</form>`,`<button class="btn" data-cancel>Cancel</button><button class="btn primary" id="obj-save">Save Objection</button>`);$('[data-cancel]').onclick=closeModal;$('#obj-save').onclick=async()=>{try{await api(`/api/leads/${id}/objections`,{method:'POST',body:JSON.stringify(formData($('#obj-form')))});closeModal();toast('Objection recorded');renderLead(id,'commercial')}catch(e){toast(e.message,'error')}}}
function openObjectionUpdate(objId,d){const o=d.objections.find(x=>Number(x.id)===Number(objId));if(!o)return;modal('Update Objection',`<div class="verification-required small"><b>${esc(o.category||o.objection)}</b><p>${esc(o.customer_comment||'')}</p></div><form id="obj-update" class="form-grid">${textarea('salesperson_response','Salesperson Response',o.salesperson_response||o.ai_suggested_response||'',4)}${textarea('salesperson_notes','Notes',o.salesperson_notes||'',3)}${select('resolution_status','Resolution',o.resolution_status,['OPEN','RESPONDED','RESOLVED','LOST'])}</form>`,`<button class="btn" data-cancel>Cancel</button><button class="btn primary" id="obj-update-save">Update</button>`);$('[data-cancel]').onclick=closeModal;$('#obj-update-save').onclick=async()=>{try{await api(`/api/objections/${objId}`,{method:'PATCH',body:JSON.stringify(formData($('#obj-update')))});closeModal();toast('Objection updated');renderLead(d.lead.id,'commercial')}catch(e){toast(e.message,'error')}}}
function openOrderAction(id,action,d){if(action==='LOST'){modal('Mark Lead Lost',`<form id="lost-form" class="form-grid">${select('reason','Lost Reason','Price',['Price','Competitor','No Budget','No Response','Wrong Requirement','Delivery','Technical','Cancelled','Duplicate','Other'])}${textarea('notes','Notes','',3)}</form>`,`<button class="btn" data-cancel>Cancel</button><button class="btn danger" id="lost-save">Mark Lost</button>`);$('[data-cancel]').onclick=closeModal;$('#lost-save').onclick=async()=>{try{const b=formData($('#lost-form'));b.action='LOST';await api(`/api/leads/${id}/outcome`,{method:'POST',body:JSON.stringify(b)});closeModal();toast('Lead marked lost');renderLead(id,'commercial')}catch(e){toast(e.message,'error')}};return}
  if(action==='ORDER CONFIRMED'){modal('Confirm Order',`<form id="won-form" class="form-grid">${input('order_value','Order Value',d.lead.expected_value||'','number','min="0"')}${input('order_date','Order Date',new Date().toISOString().slice(0,10),'date')}${input('po_number','PO Number','')}${textarea('notes','Notes','',3)}</form>`,`<button class="btn" data-cancel>Cancel</button><button class="btn primary" id="won-save">Confirm Order</button>`);$('[data-cancel]').onclick=closeModal;$('#won-save').onclick=async()=>{try{const b=formData($('#won-form'));b.action='ORDER CONFIRMED';await api(`/api/leads/${id}/outcome`,{method:'POST',body:JSON.stringify(b)});closeModal();toast('Order confirmed');renderLead(id,'commercial')}catch(e){toast(e.message,'error')}};return}
  api(`/api/leads/${id}/outcome`,{method:'POST',body:JSON.stringify({action})}).then(()=>{toast(action);renderLead(id,'commercial')}).catch(e=>toast(e.message,'error'));
}
async function moveNextStage(id,d){const idx=STAGES.indexOf(d.lead.pipeline_stage),next=STAGES[Math.min(STAGES.length-1,idx+1)];if(!next||next===d.lead.pipeline_stage)return toast('Already at final stage','error');try{await api(`/api/leads/${id}/stage`,{method:'PATCH',body:JSON.stringify({stage:next})});toast(`Moved to ${label(next)}`);renderLead(id,state.leadTab)}catch(e){toast(e.message,'error')}}

function responseSla(receivedAt){const mins=Math.max(0,Math.floor((Date.now()-new Date(receivedAt||Date.now()).getTime())/60000));if(mins<=15)return{label:'Excellent',cls:'green',text:`${mins} min old — contact within SLA`};if(mins<=30)return{label:'Attention',cls:'amber',text:`${mins} min old — contact now`};if(mins<=60)return{label:'Urgent',cls:'orange',text:`${mins} min old — response delayed`};return{label:'Overdue',cls:'red',text:`${mins} min old — immediate action required`}}
function generatedValue(d){const pi=d.product_intelligence?.[0],r=d.requirements?.[0]||{},p=pi?.best_match?.product;const bits=[];if(r.required_accuracy)bits.push(`required ${r.required_accuracy} accuracy/readability`);if(r.required_range)bits.push(`required ${r.required_range} range/capacity`);if(r.application)bits.push(`your ${r.application} application`);const product=p?.name||r.product_name||'recommended solution';return `The recommended ${product} is being selected around ${bits.length?bits.join(', '):'the confirmed customer requirement'}. We will use only verified specifications, price, delivery and commercial terms in the final offer.`}
function openStagePanel(id,no,d){const row=d.playbook?.find(x=>Number(x.stage_no)===no),existing=row?.stage_data||{};let body='',saveLabel='Complete Stage';if(no===1)body=`<p class="stage-help">Verify Need, Budget, Urgency, Authority, Timeline and Purchase Intent. The score recalculates automatically.</p><button class="btn primary full" id="stage-special">Open Qualification</button>`;
  else if(no===2){const sla=responseSla(d.lead.received_at);body=`<div class="sla-banner ${sla.cls}"><b>${sla.label}</b><span>${esc(sla.text)}</span></div><form id="stage-form" class="form-grid">${select('method','Method',existing.method||'CALL',['CALL','WHATSAPP','EMAIL'])}${select('outcome','Outcome',existing.outcome||'CONNECTED',['CONNECTED','NO ANSWER','BUSY','WRONG NUMBER','CALL LATER','WHATSAPP SENT','EMAIL SENT'])}${textarea('detail','Call / Message Notes',existing.detail||'',3)}</form><p class="form-note">This records first response time, last contact and contact attempts.</p>`;}
  else if(no===3)body=`<p class="stage-help">Ask the generated product-specific discovery questions and save answers directly into Buyer Requirements.</p><button class="btn primary full" id="stage-special">Open Discovery Questions</button>`;
  else if(no===4){const val=existing.customer_value||generatedValue(d);body=`<form id="stage-form">${textarea('customer_value','AI Generated Value Proposition',val,5)}</form><div class="actions"><button class="btn sm" id="copy-value">Copy</button><a class="btn sm" href="mailto:${esc(d.customer.email||'')}?body=${encodeURIComponent(val)}">Use in Email</a><a class="btn sm" target="_blank" href="${d.customer.phone?`https://wa.me/${String(d.customer.phone).replace(/\D/g,'')}?text=${encodeURIComponent(val)}`:'#'}">Use in WhatsApp</a></div>`}
  else if(no===5){const pi=d.product_intelligence?.[0];body=`<div class="solution-grid stage-solutions">${pi?.best_match?`<div><span>BEST MATCH</span><b>${esc(pi.best_match.product?.name||'')}</b><small>${esc(pi.best_match.product?.model||'')}</small><strong>${pi.best_match.confidence||0}%</strong></div>`:''}${(pi?.alternatives||[]).slice(0,3).map((a,i)=>`<div><span>${i===0?'ALTERNATIVE':i===1?'ECONOMY OPTION':'PREMIUM OPTION'}</span><b>${esc(a.product?.name||'')}</b><small>${esc(a.product?.model||'')}</small><strong>${a.confidence||0}%</strong></div>`).join('')}</div><form id="stage-form">${textarea('recommended_solution','Recommended Solution',existing.recommended_solution||pi?.best_match?.product?.name||'',3)}${textarea('fit_reason','Why it fits',existing.fit_reason||generatedValue(d),3)}</form>`}
  else if(no===6)body=`<div class="information-pack"><b>Customer Information Pack</b><p>${esc(d.requirements?.[0]?.product_name||'')}</p><ul><li>Product / brand / model</li><li>Dynamic specifications with verification status</li><li>Description, features and applications</li><li>Price / GST only when verified</li><li>Delivery, warranty and payment terms from quotation</li></ul><div class="actions"><button class="btn sm" id="copy-pack">Copy Details</button><button class="btn sm" id="download-pack">Download Product Details</button><button class="btn sm" id="attach-quote">Attach to Quote</button></div></div><form id="stage-form">${textarea('details_shared','Details Shared',existing.details_shared||'Product details / specifications / applications',3)}${input('documents','Catalogue / Datasheet Reference',existing.documents||'')}</form>`;
  else if(no===7)body=`<div class="verification-required small"><b>Use genuine urgency only</b><p>Never fabricate stock, offer expiry, supplier price increase or delivery urgency.</p></div><form id="stage-form" class="form-grid">${select('urgency','Urgency',existing.urgency||d.lead.urgency,['IMMEDIATE','THIS WEEK','THIS MONTH','LATER','UNKNOWN'])}${input('reason','Verified Reason',existing.reason||'')}${input('source','Evidence / Source',existing.source||'')}${input('valid_until','Valid Until',existing.valid_until||'','date')}${input('stock_note','Verified Stock Note',existing.stock_note||'')}${input('delivery_note','Verified Delivery Note',existing.delivery_note||'')}</form><button class="btn full" id="no-urgency">No Verified Urgency Available</button>`;
  else if(no===8)body=`<p class="stage-help">Record the customer objection, suggested response and resolution. If the customer has no current objection, record that truthfully and continue.</p><div class="actions vertical"><button class="btn primary full" id="stage-special">Open Objections</button><button class="btn full" id="no-objection">No Current Objection</button></div>`;
  else if(no===9)body=`<p class="stage-help">Upload the quotation already prepared by Nunes. CRM quotation creation is disabled.</p><button class="btn primary full" id="stage-special">Upload Existing Quotation</button>`;
  else if(no===10)body=`<p class="stage-help">When requirement, product and price are confirmed, clearly ask: “Shall we proceed with the order?”</p><div class="actions vertical"><button class="btn primary" data-stage-order="ORDER CONFIRMED">Order Confirmed</button><button class="btn" data-stage-order="WAITING FOR PO">Waiting for PO</button><button class="btn" data-stage-order="WAITING FOR APPROVAL">Waiting Approval</button><button class="btn" data-stage-order="FOLLOW-UP REQUIRED">Follow-Up Required</button><button class="btn" data-stage-order="NOT READY">Not Ready</button></div>`;
  else if(no===11)body=`<p class="stage-help">Schedule the next follow-up with type, owner, priority and reason.</p><button class="btn primary full" id="stage-special">Schedule Follow-Up</button>`;
  else if(no===12)body=`<form id="stage-form" class="form-grid">${input('future_requirement','Future Product Requirement',existing.future_requirement||d.nurture?.future_requirement||'')}${input('expected_purchase_month','Expected Purchase Month',existing.expected_purchase_month||d.nurture?.expected_purchase_month||'','month')}${input('preferred_brands','Preferred Brands',existing.preferred_brands||d.nurture?.preferred_brands||'')}${input('products_of_interest','Products of Interest',existing.products_of_interest||d.nurture?.products_of_interest||'')}${input('future_followup_at','Next Relationship Follow-Up',existing.future_followup_at||d.nurture?.next_relationship_followup_at||'','datetime-local')}${textarea('relationship_notes','Relationship Notes',existing.relationship_notes||d.nurture?.notes||'',3)}<label class="check full"><input type="checkbox" name="move_to_nurture"><span>Move current lead to NURTURE</span></label></form>`;
  modal(`${no}. ${PLAYBOOK[no-1][1]}`,body,`<button class="btn" data-cancel>Close</button>${[1,3,8,9,10,11].includes(no)?'':`<button class="btn primary" id="stage-save">${saveLabel}</button>`}`);$('[data-cancel]').onclick=closeModal;
  if(no===1)$('#stage-special').onclick=()=>{closeModal();openQualification(id,d)};if(no===3)$('#stage-special').onclick=()=>{closeModal();openRequirement(id,d,true)};if(no===8)$('#stage-special').onclick=()=>{closeModal();openObjection(id)};if(no===9)$('#stage-special').onclick=()=>{closeModal();openQuotationUpload(id,d)};if(no===11)$('#stage-special').onclick=()=>{closeModal();openFollowup(id,d)};
  if(no===4)$('#copy-value').onclick=()=>navigator.clipboard.writeText($('#stage-form [name="customer_value"]').value).then(()=>toast('Copied'));
  if(no===6){const pack=buildInfoPack(d);$('#copy-pack').onclick=()=>navigator.clipboard.writeText(pack).then(()=>toast('Copied'));$('#download-pack').onclick=()=>downloadText(`${d.requirements?.[0]?.product_name||'product'}-details.txt`,pack);$('#attach-quote').onclick=()=>{closeModal();openQuotationUpload(id,d)}}
  if(no===7)$('#no-urgency').onclick=async()=>{try{await api(`/api/leads/${id}/playbook/7`,{method:'PATCH',body:JSON.stringify({status:'COMPLETED',data:{no_verified_urgency:true},notes:'No verified urgency available — reviewed without fabrication.'})});closeModal();toast('Stage 7 reviewed truthfully');renderLead(id,state.leadTab)}catch(e){toast(e.message,'error')}};
  if(no===8)$('#no-objection').onclick=async()=>{try{await api(`/api/leads/${id}/playbook/8`,{method:'PATCH',body:JSON.stringify({status:'COMPLETED',data:{no_objection:true},notes:'Customer has no current objection.'})});closeModal();toast('Stage 8 completed — no current objection');renderLead(id,state.leadTab)}catch(e){toast(e.message,'error')}};
  $$('[data-stage-order]').forEach(b=>b.onclick=()=>{closeModal();openOrderAction(id,b.dataset.stageOrder,d)});
  $('#stage-save')?.addEventListener('click',async()=>{try{const f=$('#stage-form'),data=f?formData(f):{};if(f?.querySelector('[name="move_to_nurture"]'))data.move_to_nurture=f.querySelector('[name="move_to_nurture"]').checked;await api(`/api/leads/${id}/playbook/${no}`,{method:'PATCH',body:JSON.stringify({status:'COMPLETED',data,notes:`Stage ${no} completed from structured workflow`})});closeModal();toast(`Stage ${no} completed`);renderLead(id,state.leadTab)}catch(e){toast(e.message,'error')}})
}
function buildInfoPack(d){const r=d.requirements?.[0]||{},pi=d.product_intelligence?.[0]||{},p=pi.best_match?.product||{},price=d.price_intelligence||{};return [`NUNES INSTRUMENTATION — PRODUCT DETAILS`,`Product: ${r.product_name||''}`,`Brand: ${p.brand||r.requested_brand||'Not Available'}`,`Model: ${p.model||r.requested_model||'Not Available'}`,`Description: ${pi.description||''}`,'','SPECIFICATIONS',...(pi.specs||[]).map(s=>`${s.spec_key}: ${s.spec_value} [${s.verification_status||'NEEDS VERIFICATION'} | ${s.source||'Unknown'}]`),'','FEATURES',...(pi.features||[]).map(x=>`- ${x}`),'','APPLICATIONS',...(pi.applications||[]).map(x=>`- ${x}`),'',`Price: ${price.status==='AVAILABLE'?fmtMoney(price.suggested_selling):'PRICE VERIFICATION REQUIRED'}`,`GST: ${price.status==='AVAILABLE'&&price.gst_percent?price.gst_percent+'%':'Not Available'}`,`Delivery: ${price.lead_time||'Not Available'}`].join('\n')}
function downloadText(name,text){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type:'text/plain'}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}


