let simpleControlSeq=0;
function cleanFormValue(v){const x=String(v??'').trim();return /^(not available|needs verification|needs confirmation|not confirmed)$/i.test(x)?'':x}
function simpleId(name,suffix=''){return `sf-${String(name||'field').replace(/[^a-z0-9_-]+/gi,'-')}${suffix?`-${suffix}`:''}`}
