function simpleMoneyField(name,labelText,value='',attrs='',full=false){const id=simpleId(name);return `<div class="simple-field ${full?'full':''}"><label for="${id}">${esc(labelText)}</label><div class="simple-money-input"><span aria-hidden="true">₹</span><input id="${id}" name="${esc(name)}" type="number" value="${esc(cleanFormValue(value))}" ${attrs}></div></div>`}
